SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, si.warehouse_org_id AS inventoryOrgId, sd.qty AS salesQty, sd.amount AS salesAmount, sd.is_gift, sd.is_close, sd.remark, si.warehouse_id, sd.currency, sd.currency_symbol FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted = FALSE
AND si.id = #{id}
AND sd.sku_no IN
#{skuNo}

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.is_gift, sd.is_close, sd.remark, sd.delivery_status, si.approve_status FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE
AND si.approve_status IN
#{approve}

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.is_gift, sd.is_close, sd.remark, sd.delivery_status, si.approve_status FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE
AND sd.delivery_status IN
#{deliveryStatus}
